  <script>
    const list = document.getElementById('todo-list');
    const todoErrors = new Map();
    let cachedTodos = [];

    function renderTodos(data) {
      cachedTodos = data;
      list.innerHTML = data.map(item => {
        const error = todoErrors.get(item.id);
        return `
          <li data-id="${item.id}">
