            </div>
            ${error ? `<div class="todo-error" role="alert">${error}</div>` : ''}
          </li>
        `;
      }).join('');
    }

    async function fetchTodos() {
      const res = await fetch('/api/todos');
      const data = await res.json();
      renderTodos(data);
