      const todo = cachedTodos.find(item => item.id === id);
      if (!todo) return;

      const previousCompleted = todo.completed;
      todo.completed = !todo.completed;
      todoErrors.delete(id);
      renderTodos(cachedTodos);

      try {
        const res = await fetch(`/api/todos/${id}`, {
